openwrt_dts.qca9531_tplink_tl-wr810n-v1.dts:
// SPDX-License-Identifier: GPL-2.0-or-later OR MIT

#include "qca953x_tplink_tl-wr810n.dtsi"

/ {
	compatible = "tplink,tl-wr810n-v1", "qca,qca9531";
	model = "TP-Link TL-WR810N v1";

	reg_usb_vbus: reg_usb_vbus {
		compatible = "regulator-fixed";
		regulator-name = "usb_vbus";
		regulator-min-microvolt = <5000000>;
		regulator-max-microvolt = <5000000>;
		gpios = <&gpio 11 GPIO_ACTIVE_HIGH>;
		enable-active-high;
		regulator-always-on;
	};
};

&usb0 {
	status = "okay";
};

&usb_phy {
	status = "okay";
};

openwrt_dts.qca953x_tplink_tl-wr810n.dtsi:
// SPDX-License-Identifier: GPL-2.0-or-later OR MIT

#include "qca953x.dtsi"

#include <dt-bindings/gpio/gpio.h>
#include <dt-bindings/input/input.h>

/ {
	aliases {
		led-boot = &led_system;
		led-failsafe = &led_system;
		led-running = &led_system;
		led-upgrade = &led_system;
		label-mac-device = &eth1;
	};

	leds {
		compatible = "gpio-leds";

		led_system: system {
			label = "blue:system";
			gpios = <&gpio 13 GPIO_ACTIVE_LOW>;
		};
	};

	keys {
		compatible = "gpio-keys";

		reset {
			label = "Reset button";
			linux,code = <KEY_RESTART>;
			gpios = <&gpio 12 GPIO_ACTIVE_LOW>;
			debounce-interval = <60>;
		};

		switch_b0 {
			label = "switch_b0";
			linux,input-type = <EV_SW>;
			linux,code = <BTN_0>;
			gpios = <&gpio 1 GPIO_ACTIVE_HIGH>;
			debounce-interval = <60>;
		};

		switch_b1 {
			label = "switch_b1";
			linux,input-type = <EV_SW>;
			linux,code = <BTN_1>;
			gpios = <&gpio 0 GPIO_ACTIVE_HIGH>;
			debounce-interval = <60>;
		};
	};
};

&spi {
	status = "okay";

	flash@0 {
		compatible = "jedec,spi-nor";
		reg = <0>;
		spi-max-frequency = <25000000>;

		partitions {
			compatible = "fixed-partitions";
			#address-cells = <1>;
			#size-cells = <1>;

			uboot: partition@0 {
				label = "u-boot";
				reg = <0x000000 0x020000>;
				read-only;

				nvmem-layout {
					compatible = "fixed-layout";
					#address-cells = <1>;
					#size-cells = <1>;

					macaddr_uboot_1fc00: macaddr@1fc00 {
						compatible = "mac-base";
						reg = <0x1fc00 0x6>;
						#nvmem-cell-cells = <1>;
					};
				};
			};

			partition@20000 {
				compatible = "tplink,firmware";
				label = "firmware";
				reg = <0x020000 0x7d0000>;
			};

			partition@7f0000 {
				label = "art";
				reg = <0x7f0000 0x010000>;
				read-only;

				nvmem-layout {
					compatible = "fixed-layout";
					#address-cells = <1>;
					#size-cells = <1>;

					cal_art_1000: calibration@1000 {
						reg = <0x1000 0x440>;
					};
				};
			};
		};
	};
};

&eth0 {
	status = "okay";

	phy-handle = <&swphy4>;

	nvmem-cells = <&macaddr_uboot_1fc00 1>;
	nvmem-cell-names = "mac-address";
};

&eth1 {
	nvmem-cells = <&macaddr_uboot_1fc00 0>;
	nvmem-cell-names = "mac-address";
};

&wmac {
	status = "okay";

	nvmem-cells = <&macaddr_uboot_1fc00 0>, <&cal_art_1000>;
	nvmem-cell-names = "mac-address", "calibration";
};
